import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"旅","description":"周易正义 - 旅","frontmatter":{"title":"旅","description":"周易正义 - 旅"},"headers":[],"relativePath":"zh/classics/zhengyi/056.md","filePath":"zh/classics/zhengyi/056.md"}'),l={name:"zh/classics/zhengyi/056.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>火山旅</p></blockquote><blockquote><p>卦辞：小亨，旅贞吉。</p></blockquote><blockquote><p>彖曰：旅小亨，柔得中乎外，而顺乎刚，止而丽乎明，是以小亨旅贞吉也。旅之时义大矣哉！</p></blockquote><h1 id="旅" tabindex="-1">旅 <a class="header-anchor" href="#旅" aria-label="Permalink to “旅”">​</a></h1><p>王弼：不足全夫贞吉之道，唯足以为旅之贞吉，故特重曰“旅，贞吉”也。</p><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：旅者，客寄之名，羁旅之称，失其本居，而寄他方，谓之为旅。既为羁旅，苟求仅存，虽得自通，非甚光大，故《旅》之为义，小亨而巳，故曰“旅，小亨”。羁旅而获小亨，是旅之正吉，故曰“旅，贞吉”也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="旅-小亨-柔得中乎外-而顺乎刚-止而丽乎明-是以-小亨-旅贞吉-也。-​" tabindex="-1">“旅，小亨”，柔得中乎外，而顺乎刚，止而丽乎明，是以“小亨，旅贞吉”也。 ​ <a class="header-anchor" href="#旅-小亨-柔得中乎外-而顺乎刚-止而丽乎明-是以-小亨-旅贞吉-也。-​" aria-label="Permalink to ““旅，小亨”，柔得中乎外，而顺乎刚，止而丽乎明，是以“小亨，旅贞吉”也。 ​”">​</a></h3><p>王弼：夫物失其主则散，柔乘於刚则乖。既乖且散，物皆羁旅，何由得小亨而吉乎？夫阳为物长，而阴皆顺阳。唯六五乘刚，而复得中乎外，以承于上，阴凶顺阳，不为乖逆。止而丽明，动不履妄，虽不及刚得尊位，恢弘大通，是以小亨。令附旅者，不失其正，得其所安也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>“《彖》曰”至“贞吉也”。○正义曰：“旅，小亨”者，举《经》文也。柔得中乎外而顺乎刚，止而丽乎明，是以“小亨”。“旅贞吉”者，此就六五及二体，释旅得亨贞之义，柔处於外，弱而为客之象，若所讬不得其主，得主而不能顺从，则乖逆而离散，何由得自通而贞吉乎？今柔虽处外而得中顺阳，则是得其所讬，而顺从於主。又止而丽明，动不履妄，故能於寄旅之时，得通而正，不失所安也。</p><h3 id="旅之时义大矣哉-​" tabindex="-1">旅之时义大矣哉！ ​ <a class="header-anchor" href="#旅之时义大矣哉-​" aria-label="Permalink to “旅之时义大矣哉！ ​”">​</a></h3><p>王弼：旅者大散，物皆失其所居之时也。咸失其居，物愿所附，岂非知者有为之时？</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此叹美寄旅之时，物皆失其所居。若能与物为附，使旅者获安，非小才可济，惟大智能然。故曰“旅之时义大矣哉”。</p><h2 id="《象》曰-山上有火-旅。君子以明慎用刑而不留狱。-​" tabindex="-1">《象》曰：山上有火，旅。君子以明慎用刑而不留狱。 ​ <a class="header-anchor" href="#《象》曰-山上有火-旅。君子以明慎用刑而不留狱。-​" aria-label="Permalink to “《象》曰：山上有火，旅。君子以明慎用刑而不留狱。 ​”">​</a></h2><p>王弼：止以明之，刑戮详也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：火在山上，逐草而行，势不久留，故为旅象。又上下二体，艮止离明，故君子象此，以静止明察，审慎用刑，而不稽留狱讼。</p><h2 id="初六-旅琐琐-斯其所取灾。-​" tabindex="-1">初六：旅琐琐，斯其所取灾。 ​ <a class="header-anchor" href="#初六-旅琐琐-斯其所取灾。-​" aria-label="Permalink to “初六：旅琐琐，斯其所取灾。 ​”">​</a></h2><p>王弼：最处下极，寄旅不得所安，而为斯贱之役，所取致灾，志穷且困。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“旅琐琐，斯其所取灾”者，琐琐者，细小卑贱之貌也。初六当旅之时，最处下极，是寄旅不得所安，而为斯卑贱之役。然则为斯卑贱劳役，由其处於穷下，故致此灾，故曰“旅琐琐斯其所取灾”也。</p><h3 id="《象》曰-旅琐琐-志穷灾也。-​" tabindex="-1">《象》曰：“旅琐琐”，志穷灾也。 ​ <a class="header-anchor" href="#《象》曰-旅琐琐-志穷灾也。-​" aria-label="Permalink to “《象》曰：“旅琐琐”，志穷灾也。 ​”">​</a></h3><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“志穷灾”，志意穷困，自取此灾也。</p><h2 id="六二-旅即次-怀其资-得童仆贞。-​" tabindex="-1">六二：旅即次，怀其资，得童仆贞。 ​ <a class="header-anchor" href="#六二-旅即次-怀其资-得童仆贞。-​" aria-label="Permalink to “六二：旅即次，怀其资，得童仆贞。 ​”">​</a></h2><p>王弼：次者，可以安行旅之地也。怀，来也。得位居中，体柔奉上，以此寄旅，必获次舍。怀来资货，得童仆之所正也。旅不可以处盛，故其美尽於童仆之正也。过斯以往，则见害矣。童仆之正，义足而巳。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“旅即次，怀其资，得童仆贞”者，得位居中，体柔承上，以此而为寄旅，必为主君所安，旅得次舍，怀来资货，又得童仆之正，不同初六贱役，故曰“旅即次，怀其资，得童仆贞”。</p><h3 id="《象》曰-得童仆贞-终无尤也。-​" tabindex="-1">《象》曰：“得童仆贞”，终无尤也。 ​ <a class="header-anchor" href="#《象》曰-得童仆贞-终无尤也。-​" aria-label="Permalink to “《象》曰：“得童仆贞”，终无尤也。 ​”">​</a></h3><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“终无尤”者，旅不可以处盛，盛则为物所害。今惟正於童仆，则终保无咎也。</p><h2 id="九三-旅焚其次-丧其童仆-贞厉。-​" tabindex="-1">九三：旅焚其次，丧其童仆，贞厉。 ​ <a class="header-anchor" href="#九三-旅焚其次-丧其童仆-贞厉。-​" aria-label="Permalink to “九三：旅焚其次，丧其童仆，贞厉。 ​”">​</a></h2><p>王弼：居下体之上，与二相得，以寄旅之身而为施下之道，与萌侵权，主之所疑也，故次焚仆丧，而身危也。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>“九三旅焚其次”至“贞厉”。○正义曰：“旅焚其次，丧其童仆，贞厉”者，九三居下体之上，下据於二，上无其应，与二相得，是欲自尊而惠施於下也。以羁旅之身而为惠下之道，是与萌侵权，为主君之所疑也。为君主所疑，则被黜而见害，故焚其次舍，丧其童仆之正而身危也。○注“与萌”至“所疑也”。正义曰：“与萌侵权”者，言与得政事之萌，渐侵夺主君之权势，若齐之田氏，故为主所疑也。</p><h3 id="《象》曰-旅焚其次-亦以伤矣。以旅与下-其义丧也。-​" tabindex="-1">《象》曰：“旅焚其次”，亦以伤矣。以旅与下，其义丧也。 ​ <a class="header-anchor" href="#《象》曰-旅焚其次-亦以伤矣。以旅与下-其义丧也。-​" aria-label="Permalink to “《象》曰：“旅焚其次”，亦以伤矣。以旅与下，其义丧也。 ​”">​</a></h3><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“亦以伤矣”者，言失其所安，亦可悲伤也。“其义丧”者，言以旅与下，理是丧亡也。</p><h2 id="九四-旅于处-得其资斧-我心不快。-​" tabindex="-1">九四：旅于处，得其资斧，我心不快。 ​ <a class="header-anchor" href="#九四-旅于处-得其资斧-我心不快。-​" aria-label="Permalink to “九四：旅于处，得其资斧，我心不快。 ​”">​</a></h2><p>王弼：斧所以斫除荆棘，以安其舍者也。虽处上体之下，不先於物，然而不得其位，不获平坦之地，客于所处，不得其次，而得其资斧之地，故其心不快也。</p><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“旅于处，得其资斧，我心不快”者，九四处上体之下，不同九三之自尊，然不得其位，犹寄旅之人，求其次舍，不获平坦之所，而得用斧之地。言用斧除荆棘，然后乃处，故曰“旅于处，得其资斧”也。求安处而得资斧之地，所以其心不快也。</p><h3 id="《象》曰-旅于处-未得位也。-得其资斧-心未快也。-​" tabindex="-1">《象》曰：“旅于处”，未得位也。“得其资斧”，心未快也。 ​ <a class="header-anchor" href="#《象》曰-旅于处-未得位也。-得其资斧-心未快也。-​" aria-label="Permalink to “《象》曰：“旅于处”，未得位也。“得其资斧”，心未快也。 ​”">​</a></h3><h2 id="六五-射雉一矢-亡。终以誉命。-​" tabindex="-1">六五：射雉一矢，亡。终以誉命。 ​ <a class="header-anchor" href="#六五-射雉一矢-亡。终以誉命。-​" aria-label="Permalink to “六五：射雉一矢，亡。终以誉命。 ​”">​</a></h2><p>王弼：射雉以一矢，而复亡之，明虽有雉，终不可得矣。寄旅而进，虽处于文明之中，居于贵位，此位终不可有也。以其能知祸福之萌，不安其处以乘其下，而上承於上，故终以誉而见命也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>“六五射雉”至“以誉命”。○正义曰：“射雉一矢亡，终以誉命”者，羁旅不可以处盛位，六五以羁旅之身，进居贵位，其位终不可保，譬之射雉，惟有一矢，射之而复亡失其矢，其雉终不可得，故曰“射雉一矢亡”也。然处文明之内，能照祸福之几，不乘下以侵权，而承上以自保，故得终以美誉而见爵命，故曰“终以誉命”也。</p><h3 id="《象》曰-终以誉命-上逮也。-​" tabindex="-1">《象》曰：“终以誉命”，上逮也。 ​ <a class="header-anchor" href="#《象》曰-终以誉命-上逮也。-​" aria-label="Permalink to “《象》曰：“终以誉命”，上逮也。 ​”">​</a></h3><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“上逮”者，逮，及也，以能承及於上，故得“终以誉命”也。</p><h2 id="上九-鸟焚其巢-旅人先笑后号咷。丧牛于易-凶。-​" tabindex="-1">上九：鸟焚其巢，旅人先笑后号咷。丧牛于易，凶。 ​ <a class="header-anchor" href="#上九-鸟焚其巢-旅人先笑后号咷。丧牛于易-凶。-​" aria-label="Permalink to “上九：鸟焚其巢，旅人先笑后号咷。丧牛于易，凶。 ​”">​</a></h2><p>王弼：居高危而以为宅，巢之谓也。客旅得上位，故先笑也。以旅而处于上极，众之所嫉也。以不亲之身而当被害之地，必凶之道也，故曰“后号咷”。牛者，稼穑之资。以旅处上，无所同嫉，故“丧牛于易”，不在於难。物莫之与，危而不扶，丧牛于易，终莫之闻。莫之闻，则伤之者至矣。</p><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“鸟焚其巢，旅人先笑后号咷，丧牛于易，凶”者，最居於上，如鸟之巢，以旅处上，必见倾夺，如鸟巢之被焚，故曰“鸟焚其巢”也。客得上位，所以“先笑”。凶害必至，故“后号咷”。无所同嫉，丧其稼穑之资，理在不难，故曰“丧牛于易”。物莫之与，则伤之者至矣，故曰“凶”也。</p><h3 id="《象》曰-以旅在上-其义焚也。-丧牛于易-终莫之闻也。-​" tabindex="-1">《象》曰：以旅在上，其义焚也。“丧牛于易”，终莫之闻也。 ​ <a class="header-anchor" href="#《象》曰-以旅在上-其义焚也。-丧牛于易-终莫之闻也。-​" aria-label="Permalink to “《象》曰：以旅在上，其义焚也。“丧牛于易”，终莫之闻也。 ​”">​</a></h3><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“终莫之闻也”者，众所同疾，危而不扶，至于丧牛于易，终无以一言告之，使闻而悟也。</p>',60)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
